import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"差量引擎","description":"hdiffpatch CGO HDIFF13& vs 历史 KVDIFFHP1。magic 分流。构建要 C++ 工具链。","frontmatter":{"title":"差量引擎","description":"hdiffpatch CGO HDIFF13& vs 历史 KVDIFFHP1。magic 分流。构建要 C++ 工具链。"},"headers":[],"relativePath":"contribute/delta.md","filePath":"contribute/delta.md","lastUpdated":1790057721000}`),a={name:`contribute/delta.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="差量引擎" tabindex="-1">差量引擎 <a class="header-anchor" href="#差量引擎" aria-label="Permalink to “差量引擎”">​</a></h1><p>单文件二进制差量在 <code>internal/delta</code>。服务端 <strong>必须</strong> <code>CGO_ENABLED=1</code> 并带 C++ 工具链（Windows MinGW <code>g++</code> / Linux <code>g++</code> 或 <code>clang++</code> / macOS Xcode <code>clang++</code>）。运行时不再从 PATH 调用 <code>hdiffz</code>/<code>hpatchz</code>。Go SDK 仍是 <code>CGO_ENABLED=0</code>，见 SDK 文档。</p><table tabindex="0"><thead><tr><th>算法</th><th>magic</th><th>说明</th></tr></thead><tbody><tr><td>hdiffpatch（CGO）</td><td><code>HDIFF13&amp;</code></td><td>新生成未压缩官方格式；<code>DescribeAvailable</code> 为 <code>cgo</code></td></tr><tr><td>hdiffpatch 历史</td><td><code>KVDIFFHP1</code></td><td>仅 Patch，不是官方 .hdiff</td></tr><tr><td>bsdiff</td><td><code>BSDIFF40</code></td><td><code>pure-go</code></td></tr><tr><td>xdelta3 / VCDIFF</td><td><code>D6 C3 C4</code></td><td>RFC 3284 二进制 magic，不是 ASCII；<code>pure-go</code></td></tr></tbody></table><p><code>Patch</code> 按 magic 分流，禁止交叉解码。未知算法 HTTP <code>DELTA_ALGO_UNSUPPORTED</code>。管理 <code>POST .../artifacts/delta</code> 入队 Job。HTTP 路径不得 <code>archive/zip</code>。</p><p>官方 <code>darwin/*</code> 二进制必须在 macOS 宿主上 CGO 构建（<code>darwin/arm64</code> 原生、<code>darwin/amd64</code> 同机 <code>clang -arch x86_64</code>），不能从 Linux 无 Apple SDK 交叉。GitHub 发版工作流用钉版本的 macOS runner（<code>macos-15</code>）产出这两个目标；GitHub 是唯一 forge，十个目标里不存在「某个平台跳过」的情况，缺件时打包作业直接失败而不是伪造文件。</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};